#include <bits/stdc++.h>
using namespace std;

using LL = long long;

int dp[101][201][51][2];
int ans = 0;
string s;
int n;

void solve(int idx, int pos, int changesLeft, int dir)
{
    if (idx == static_cast<int>(s.size())) {
        if (changesLeft % 2 == 0)
            ans = max(ans, abs(pos - 100));
        return;
    }

    if (dp[idx][pos][changesLeft][dir] != -1)
        return;

    dp[idx][pos][changesLeft][dir] = 1;

    int dx = dir ? 1 : -1;

    if (s[idx] == 'F')
        solve(idx + 1, pos + dx, changesLeft, dir);
    else
        solve(idx + 1, pos, changesLeft, !dir);

    if (changesLeft > 0) {
        if (s[idx] == 'F')
            solve(idx + 1, pos, changesLeft - 1, !dir);
        else
            solve(idx + 1, pos + dx, changesLeft - 1, dir);
    }
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    memset(dp, -1, sizeof(dp));

    cin >> s >> n;
    solve(0, 100, n, 0);

    cout << ans << '\n';
    return 0;
}

